test('cancelled execution clears busy state and a new Execute starts cleanly', async ({ page }) => {
	const monitor = monitorExecutions(page);
	await openQueryPage(page);
	await setEditor(page, 'SELECT ?item WHERE { VALUES ?item { "cancelled" } }');

	let releaseRequest;
	let signalRequestReceived;
	let blockFirstExecution = true;
	const blocked = new Promise(resolve => { releaseRequest = resolve; });
	const requestReceived = new Promise(resolve => { signalRequestReceived = resolve; });
	await page.route('**/rdf4j-workbench/repositories/*/query', async route => {
		const request = route.request();
		if (!blockFirstExecution || request.method() !== 'POST'
				|| !isStreamingAccept(request.headers().accept || '')) {
			await route.continue();
			return;
		}
		blockFirstExecution = false;
		signalRequestReceived();
		await blocked;
		try {
			await route.abort();
		} catch (error) {
			// The browser aborts the held response after the Cancel action.
		}
	});

	await page.locator('#exec').click();
	await requestReceived;
	const result = page.locator('#query-results .query-result-layout');
	await expect(result.getByRole('button', { name: 'Cancel query' })).toBeVisible();
	const cancelRequest = page.waitForRequest(request => request.method() === 'POST'
		&& /\/query(?:[?#]|$)/.test(request.url())
		&& new URLSearchParams(request.postData() || '').get('action') === 'cancel-query', { timeout: 15000 });
	await result.getByRole('button', { name: 'Cancel query' }).click();
	await expect(result.locator('.query-result-status')).toHaveText('Query cancelled.');
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expect(page.locator('#query-cancel')).toBeDisabled();
	const cancel = await cancelRequest;
	const executionId = fieldValue(monitor.executions[0], 'query-request-id');
	expect(new URLSearchParams(cancel.postData() || '').get('query-request-id')).toBe(executionId);

	releaseRequest();
	await executeQueryAndWait(page, monitor, 'SELECT ?item WHERE { VALUES ?item { "after-cancel" } }', 2);
	await expectCompletedRows(page.locator('#query-results .query-result-status'), 1, 1);
	await expect(page.locator('#query-results tbody tr[data-query-row-index]')).toHaveCount(1);
	await expect(page.locator('#query-results .query-result-load-more')).toBeHidden();
	expect(monitor.errors).toEqual([]);
});

